/bin/bash -lc 'set -euo pipefail
H=/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/bin/hgit; BASE=c56d433e8a99a82babf50aecb3e6fec48410e2a2; HEAD=$($H rev-parse HEAD); T=$(mktemp -d); trap '"'rm -rf \""'$T"'"' EXIT; for tag in base head; do if [ \""'$tag" = base ]; then c=$BASE; else c=$HEAD; fi; mkdir -p "$T/$tag"; "$H" archive --format=tar "$c" MainProjects/Algebraic-Jacobian-Challenge | tar -xf - -C "$T/$tag" --strip-components=2; done; python3 -u - "$T" <<'"'PY'
import pathlib,sys
from archon_horizon.search.index import extract_declarations
root=pathlib.Path(sys.argv[1])
def split_top(sig):
 d=0
 for i,ch in enumerate(sig):
  if ch in '([{': d+=1
  elif ch in ')]}': d=max(0,d-1)
  elif ch==':' and d==0 and not (i+1<len(sig) and sig[i+1]=='='): return sig[:i],sig[i+1:]
 return sig,''
def direct(tag):
 out={}
 pdir=root/tag/'AlgebraicJacobian'
 for p in pdir.rglob('*.lean'):
  for x in extract_declarations(p.read_text(errors='replace'),library='AJC',file=str(p.relative_to(pdir))):
   pre,res=split_top(x.signature)
   if '.RepresentableBy' in res and '.RepresentableBy' not in pre: out[x.name]=(x.file,x.line,x.signature)
 return out
b=direct('base'); h=direct('head')
print('ADDED')
for n in sorted(h.keys()-b.keys()): print(n,h[n][0],h[n][1],h[n][2])
print('REMOVED')
for n in sorted(b.keys()-h.keys()): print(n,b[n][0],b[n][1])
PY"

